CREATE TABLE IF NOT EXISTS tabor_coin_market_observations (id INTEGER PRIMARY KEY AUTOINCREMENT,symbol TEXT NOT NULL,network TEXT,contract_address TEXT,price_usd REAL,market_cap_usd REAL,volume_24h_usd REAL,source_name TEXT NOT NULL,source_url TEXT,observed_at TEXT NOT NULL,verification_status TEXT NOT NULL DEFAULT 'unverified',created_at TEXT DEFAULT CURRENT_TIMESTAMP);CREATE INDEX IF NOT EXISTS tabor_coin_market_symbol_time ON tabor_coin_market_observations(symbol,observed_at DESC);CREATE TABLE IF NOT EXISTS tabor_automation_runs (id INTEGER PRIMARY KEY AUTOINCREMENT,job_type TEXT NOT NULL,run_at TEXT DEFAULT CURRENT_TIMESTAMP,result_json TEXT NOT NULL,status TEXT NOT NULL);